<https://example.org/openevidence/questions/q_asthma_efficacy> a holon:ClinicalQuestionHolon ;
  oeq:hasFact [
    a oeq:Fact ;
    rdf:subject <https://example.org/openevidence/drugs/salbutamol> ;
    oe:treats <https://example.org/openevidence/diseases/asthma> ;
    confidence 0.93 ;
    level "Level-1A"^^xsd:string ;
    source <https://example.org/openevidence/sources/41005695> ;
    effectiveness "effective"^^xsd:string
